const category = (id: string) => CATEGORIES.find((entry) => entry.id === id)!
const unit = (categoryId: string, unitId: string) =>
  category(categoryId).units.find((entry) => entry.id === unitId)!

/** convertUnit followed by the panel's formatNumber. */
export function convert(categoryId: string, value: number, fromId: string, toId: string): string {
  const from = unit(categoryId, fromId)
  const to = unit(categoryId, toId)
  const result = ((value + (from.offset ?? 0)) * from.toBase) / to.toBase - (to.offset ?? 0)
  if (result !== 0 && (Math.abs(result) < 1e-6 || Math.abs(result) >= 1e15))
    return result.toExponential(6)
  return String(Math.round(result * 1e9) / 1e9)
}

